actions.script:
const providers = ec.service.sync().name('org.moqui.ui.ShellServices.get#Providers').parameters({hook: 'chat-calendar'}).call() || {}
ec.web.sendJsonResponse({timeZone: ec.user.timeZone || null, timeZoneList: Array.from(ec.l10n.getAvailableTimeZones() || []),
    calendarProvider: Array.from(providers.providerList || []).length > 0})

const out = ec.service.sync().name('org.moqui.chat.ChatCalServices.create#CalEvent').parameters({chatRoomId: chatRoomId || '', title: title || '',
    startDate: startDate ? Number(startDate) : null, endDate: endDate ? Number(endDate) : null, timeZone: timeZone || null,
    allDay: String(allDay) === 'true', place: place || null, description: description || null,
    threadRootEventSeq: threadRootEventSeq ? Number(threadRootEventSeq) : null, clientRef: clientRef || null,
    roomUrl: (ec.factory.getConfValue('comms@app-root') || '/qapps/BasicComms') + '/Chat?chatRoomId=' + encodeURIComponent(chatRoomId || '')}).call() || {}
ec.web.sendJsonResponse(ec.message.hasError() ? {reasonCode: out.reasonCode || null} : {eventSeq: out.eventSeq, event: out.event, clientRef: clientRef || null})

const out = ec.service.sync().name('org.moqui.chat.ChatCalServices.answer#CalEvent').parameters({chatRoomId: chatRoomId || '',
    eventSeq: Number(eventSeq || 0), answer: answer || null,
    remindMinutes: remindMinutes != null && remindMinutes !== '' ? Number(remindMinutes) : null,
    addToCalendar: String(addToCalendar) === 'true'}).call() || {}
ec.web.sendJsonResponse(ec.message.hasError() ? {reasonCode: out.reasonCode || null} : {calEvent: out.calEvent, eventUrl: out.eventUrl || null,
    reminderSkipped: out.reminderSkipped === true, reminderFailed: out.reminderFailed === true, calendarFailed: out.calendarFailed === true})

const out = ec.service.sync().name('org.moqui.chat.ChatCalServices.update#CalEvent').parameters({chatRoomId: chatRoomId || '',
    eventSeq: Number(eventSeq || 0), title: title ?? null, startDate: startDate ? Number(startDate) : null,
    endDate: endDate ? Number(endDate) : null, timeZone: timeZone || null,
    allDay: allDay == null || allDay === '' ? null : String(allDay) === 'true', place: place ?? null, description: description ?? null}).call() || {}
ec.web.sendJsonResponse(ec.message.hasError() ? {reasonCode: out.reasonCode || null} : {calEvent: out.calEvent, changeEventSeq: out.changeEventSeq ?? null})

const out = ec.service.sync().name('org.moqui.chat.ChatCalServices.cancel#CalEvent').parameters({chatRoomId: chatRoomId || '',
    eventSeq: Number(eventSeq || 0)}).call() || {}
ec.web.sendJsonResponse(ec.message.hasError() ? {reasonCode: out.reasonCode || null} : {calEvent: out.calEvent, changeEventSeq: out.changeEventSeq ?? null})

const request = ec.web.request
const port = Number(request.serverPort || 0)
const standard = !port || (request.scheme === 'https' && port === 443) || (request.scheme === 'http' && port === 80)
const baseUrl = request.scheme + '://' + request.serverName + (standard ? '' : ':' + port)
const out = ec.service.sync().name('org.moqui.chat.ChatCalServices.get#CalEventIcs').parameters({chatRoomId: chatRoomId || '',
    eventSeq: Number(eventSeq || 0), baseUrl: baseUrl}).call() || {}
if (ec.message.hasError() || !out.fileText) { ec.web.sendJsonResponse({reasonCode: out.reasonCode || null}); return }
ec.web.sendTextResponse(out.fileText, 'text/calendar; charset=utf-8', out.fileName || 'event.ics')
